---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Donut chart: Where the agent's time went, by kind of task.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change donut-chart.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './donut-chart.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="donut-chart" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="dnx panel">
  <div class="dnx-ring"><svg viewBox="0 0 120 120"></svg><div class="dnx-c"><b class="num dnx-v">0h</b><span class="muted dnx-l">Agent time</span></div></div>
  <div class="dnx-lg"></div>
</div>
  </Fragment></div>
</div>
<script>
  import './donut-chart.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Donut chart ---------- */
.dnx{padding:var(--dm-s-4);display:flex;align-items:center;gap:var(--dm-s-5);flex-wrap:wrap;justify-content:center}
.dnx-ring{position:relative;width:150px;height:150px;flex:none}
.dnx-ring svg{width:100%;height:100%;transform:rotate(-90deg)}
.dnx-ring circle{fill:none;stroke-width:12;transition:stroke-width .35s var(--dm-ease),opacity .3s,stroke-dasharray 1s var(--dm-ease)}
.dnx-ring circle.hl{stroke-width:16}
.dnx-ring.hov circle:not(.hl){opacity:.3}
.dnx-c{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;pointer-events:none}
.dnx-ring circle{cursor:default}
.dnx-c b{font-size:14px;font-weight:500;letter-spacing:-.02em}
.dnx-c span{font-size:11.5px}
.dnx-lg{display:flex;flex-direction:column;gap:2px;flex:1;min-width:170px}
.dnx-r{display:flex;align-items:center;gap:9px;padding:6px var(--dm-s-2);border-radius:calc(9px * var(--dm-rk));font-size:13px;transition:background .2s;cursor:default}
.dnx-r.hl{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.dnx-r:hover{background:var(--dm-row)}}
.dnx-r i{width:8px;height:8px;border-radius:3px;flex:none}
.dnx-r .t{flex:1}
.dnx-r .v{color:var(--dm-muted);font-size:12px}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, stagger, tween } from '../core/core.js';
DM.def('donut-chart', (r, c) => {
  const D = [['Design reviews',14.2,'var(--dm-c1)'],['Code changes',9.6,'var(--dm-c2)'],['Research',6.1,'var(--dm-c3)'],['Copy edits',3.4,'var(--dm-c4)'],['Other',1.7,'var(--dm-faint)']];
  const tot = D.reduce((a, d) => a + d[1], 0), C = 2 * Math.PI * 48, gap = 2;
  const svg = $('svg', r), lg = $('.dnx-lg', r), ring = $('.dnx-ring', r), v = $('.dnx-v', r), l = $('.dnx-l', r);
  let off = 0;
  svg.innerHTML = D.map((d, i) => { const len = d[1] / tot * C; const s = `<circle cx="60" cy="60" r="48" stroke="${d[2]}" stroke-dasharray="0 ${C}" stroke-dashoffset="${-off}" data-i="${i}" data-len="${len - gap}"/>`; off += len; return s; }).join('');
  lg.innerHTML = D.map((d, i) => `<div class="dnx-r" data-i="${i}"><i style="background:${d[2]}"></i><span class="t">${d[0]}</span><span class="v num">${d[1]}h · ${Math.round(d[1] / tot * 100)}%</span></div>`).join('');
  const arcs = $$('circle', svg), rows = $$('.dnx-r', lg);
  const hl = i => { ring.classList.toggle('hov', i != null); arcs.forEach((a, j) => a.classList.toggle('hl', j === i)); rows.forEach((x, j) => x.classList.toggle('hl', j === i));
    if (i == null){ v.textContent = tot.toFixed(1) + 'h'; l.textContent = 'Agent time'; } else { v.textContent = D[i][1] + 'h'; l.textContent = D[i][0]; } };
  [...arcs, ...rows].forEach(el => { el.onmouseenter = () => hl(+el.dataset.i); el.onmouseleave = () => hl(null); });
  stagger(rows, 60, 150);
  v.textContent = '0.0h';
  c.later(260, () => { arcs.forEach((a, i) => c.later(i * 90, () => a.setAttribute('stroke-dasharray', `${a.dataset.len} ${C}`))); tween(0, tot, 1200, n => v.textContent = n.toFixed(1) + 'h'); });
});
